/**
 * Code Giftz — the creative-direction engine (design intelligence, §1 + §13).
 *
 * Before a plan is written, GIFTZ reads the user's request as a complete
 * DESIGN BRIEF (purpose, brand, audience, industry, personality, color and
 * typography psychology, layout composition, media/motion/responsive
 * requirements) and commits to a CREATIVE DIRECTION: one design language, one
 * palette, one typography pairing, one motion language, a hero composition
 * and a per-section visual plan. The direction is generated by the REAL
 * gateway model (never faked), schema-validated against the REAL libraries
 * (fonts, motion presets, design languages) with ONE bounded repair, and then
 * grounds every downstream prompt — the planner, the compose step and every
 * model step see the same binding direction, so all sections feel like one
 * designed artifact.
 *
 * The direction also deterministically derives a schema-valid theme/motion
 * token patch. When the model's plan forgets to apply its own direction, the
 * system prepends ONE "apply the creative direction" deterministic step —
 * through the SAME patch schema and validators, never bypassing them.
 *
 * Failure policy: direction generation is an ENHANCEMENT, not a gate. Any
 * failure (quota, timeout, invalid output after repair) degrades gracefully
 * to null and the pipeline proceeds exactly as before — never a fabricated
 * direction, never a broken turn.
 */

import { z } from "zod";

import { aiComplete, parseJsonFromText, AI_DEEP_TIMEOUT_MS } from "@/lib/ai";
import { SITE_FONTS } from "@/lib/site-fonts";
import { MOTION_EASING_IDS, getMotionPreset, motionPresetsByScope } from "@/lib/site-motion";
import type { SiteDigest } from "@/lib/ai-design/digest";
import { designPatchSchema, type DesignPatch } from "@/lib/ai-design/plan";
import type { PlanStep } from "@/lib/ai-design/plan";
import { DESIGN_LANGUAGE_IDS, DESIGN_LANGUAGES, designLanguagesDoc, matchDesignLanguages, getDesignLanguage } from "@/lib/ai-design/design-languages";
import { getPalette } from "@/lib/site-palettes";

const hexColor = z.string().regex(/^#[0-9a-fA-F]{3,8}$/);
const fontId = z.string().refine((v) => SITE_FONTS.some((f) => f.id === v), "unknown font id");
const revealPreset = z.string().refine((v) => motionPresetsByScope("reveal").some((p) => p.id === v), "unknown reveal preset");
const hoverPreset = z.string().refine((v) => motionPresetsByScope("hover").some((p) => p.id === v), "unknown hover preset");
const backgroundPreset = z.string().refine((v) => motionPresetsByScope("background").some((p) => p.id === v), "unknown background preset");

export const creativeDirectionSchema = z.object({
  designLanguage: z.enum(DESIGN_LANGUAGE_IDS),
  concept: z.string().min(20).max(600),
  understanding: z.object({
    purpose: z.string().min(3).max(300),
    brand: z.string().min(3).max(300),
    audience: z.string().min(3).max(300),
    industry: z.string().min(2).max(120),
    personality: z.string().min(3).max(300),
    colorPsychology: z.string().min(3).max(300),
    contentHierarchy: z.string().min(3).max(300),
  }),
  palette: z.object({
    background: hexColor,
    surface: hexColor,
    foreground: hexColor,
    muted: hexColor,
    accent: hexColor,
    accent2: hexColor,
    gradient: z.object({ from: hexColor, to: hexColor, angle: z.number().int().min(0).max(360) }).nullable(),
  }),
  typography: z.object({
    headingFont: fontId,
    bodyFont: fontId,
    accentFont: fontId,
    codeFont: fontId,
    typeScale: z.enum(["intimate", "balanced", "grand"]),
    headingWeight: z.enum(["light", "semibold", "bold"]),
    letterSpacing: z.enum(["tight", "normal", "wide"]),
    lineHeight: z.enum(["tight", "normal", "relaxed"]),
    rationale: z.string().min(3).max(300),
  }),
  motion: z.object({
    preset: revealPreset,
    duration: z.number().int().min(150).max(1200),
    intensity: z.number().int().min(0).max(100),
    easing: z.enum(MOTION_EASING_IDS),
    stagger: z.number().int().min(0).max(240),
    hoverPreset: hoverPreset,
    backgroundPreset: backgroundPreset,
    pageTransition: z.enum(["none", "fade", "slide", "rise", "zoom"]),
    scrollProgress: z.boolean(),
    rationale: z.string().min(3).max(300),
  }),
  layout: z.object({
    radius: z.enum(["none", "md", "full"]),
    density: z.enum(["compact", "regular", "relaxed"]),
    contentWidth: z.enum(["narrow", "regular", "wide"]),
    buttonStyle: z.enum(["sharp", "rounded", "pill", "outline"]),
    linkStyle: z.enum(["underline", "accent", "plain"]),
    imageRatio: z.enum(["4/3", "3/2", "1/1", "16/9"]),
    divider: z.enum(["none", "line", "accent"]),
    navLayout: z.enum(["inline", "stacked", "centered"]),
    surfaceOpacity: z.number().int().min(20).max(100),
    glassPreset: z.enum(["frosted", "smoked", "crystal", "aurora", "soft", "dark", "custom"]).nullable(),
    strategy: z.string().min(3).max(400),
  }),
  heroComposition: z.string().min(10).max(500),
  sectionPlan: z
    .array(z.object({ section: z.string().min(1).max(40), direction: z.string().min(3).max(300) }))
    .max(12),
  mediaDirection: z.string().min(3).max(400),
  responsiveStrategy: z.string().min(3).max(300),
});
export type CreativeDirection = z.infer<typeof creativeDirectionSchema>;

const DIRECTION_SCHEMA_DOC = `{
  "designLanguage": one of: ${DESIGN_LANGUAGE_IDS.join(", ")},
  "concept": string (20-600) — the one-paragraph design concept a creative director would pitch,
  "understanding": { "purpose", "brand", "audience", "industry", "personality", "colorPsychology", "contentHierarchy" } — each string 3-300, the design brief in seven fields,
  "palette": { "background", "surface", "foreground", "muted", "accent", "accent2": "#rrggbb" hex, "gradient": { "from": hex, "to": hex, "angle": 0-360 } or null },
  "typography": { "headingFont", "bodyFont", "accentFont", "codeFont": real font ids from the library, "typeScale": "intimate|balanced|grand", "headingWeight": "light|semibold|bold", "letterSpacing": "tight|normal|wide", "lineHeight": "tight|normal|relaxed", "rationale": string },
  "motion": { "preset": real reveal preset id, "duration": 150-1200, "intensity": 0-100, "easing": "smooth|snap|drift|swift|gentle", "stagger": 0-240, "hoverPreset": real hover preset id, "backgroundPreset": real background preset id, "pageTransition": "none|fade|slide|rise|zoom", "scrollProgress": boolean, "rationale": string },
  "layout": { "radius": "none|md|full", "density": "compact|regular|relaxed", "contentWidth": "narrow|regular|wide", "buttonStyle": "sharp|rounded|pill|outline", "linkStyle": "underline|accent|plain", "imageRatio": "4/3|3/2|1/1|16/9", "divider": "none|line|accent", "navLayout": "inline|stacked|centered", "surfaceOpacity": 20-100, "glassPreset": "frosted|smoked|crystal|aurora|soft|dark|custom" or null, "strategy": string (3-400) },
  "heroComposition": string (10-500) — exactly how the hero is composed,
  "sectionPlan": [{ "section": section type or short label (<=40), "direction": string (3-300) }] — 3-12 entries, per-section visual direction,
  "mediaDirection": string (3-400) — imagery ratios, cropping, focal strategy,
  "responsiveStrategy": string (3-300) — how the design adapts at 1280/768/390
}`;

function directionUserPrompt(args: {
  request: string;
  digest: SiteDigest;
  portfolioBlock: string;
  materialsText?: string;
  shortlist: string[];
}): string {
  const { request, digest, portfolioBlock, materialsText, shortlist } = args;
  return [
    "The user's request (verbatim — this is the design brief source; do not contradict its explicit requirements):",
    request.slice(0, 50_000),
    "",
    "Current website digest (computed — authoritative starting point; when the user asks to redesign, keep what they did not ask to change):",
    `template ${digest.template} · name "${digest.name}" · pages ${digest.pageCount} · sections ${digest.sectionCount} (${digest.sectionTypes.join(", ")})`,
    `tokens: bg ${digest.theme.background} · accent ${digest.theme.accent} · typeScale ${digest.theme.typeScale} · glass ${digest.theme.glass ? "on" : "off"}`,
    `fonts: ${digest.fonts.heading} / ${digest.fonts.body} · motion: ${digest.motion.enabled ? digest.motion.presetLabel : "disabled"}`,
    "",
    `Design languages that pre-matched the request (STRONG candidates — you may still choose another from the registry when the brief clearly points there): ${shortlist.join(", ") || "(none — pick the best fit)"}`,
    "",
    "Design-language registry:",
    designLanguagesDoc(),
    "",
    materialsText ? `Source materials (the user's own content — ground the brief in them):\n${materialsText.slice(0, 6000)}\n` : "",
    "Portfolio context (the user's real data — never contradict or fabricate it):",
    portfolioBlock.slice(0, 4000),
    "",
    "RULES:",
    "- Ground EVERYTHING in the request. When the user names colors, typography, sections, mood or motion, the direction MUST honor those exact words.",
    "- The palette must be an internally consistent, accessible set (foreground readable on background, accent distinct from foreground).",
    "- Fonts must be ids from the real library. Presets must be real ids from the motion library.",
    "- Keep motion purposeful and restrained unless the user explicitly asked for dramatic motion.",
    "- sectionPlan entries use REAL section types from this vocabulary where possible: hero, about, projects, skills, stats, collections, contact, services, experience, gallery, testimonials, process, faq, pricing, logos.",
    "Return ONLY the JSON object in exactly this schema:",
    DIRECTION_SCHEMA_DOC,
  ]
    .filter((s) => s !== "")
    .join("\n");
}

const DIRECTION_SYSTEM = [
  "You are GIFTZ acting as a senior creative director preparing an internal creative direction for a website it is about to design.",
  "You read the request as a complete design brief — purpose, brand, audience, industry, personality, color psychology, typography direction, layout composition, content hierarchy, media, motion, interaction, responsive and accessibility expectations — and commit to ONE design language and one coherent visual system.",
  "You never fabricate facts about the user; you only design. You reply with ONLY the JSON object.",
].join(" ");

function attemptDirection(raw: string): { ok: boolean; direction?: CreativeDirection; issues: string[] } {
  const parsed = parseJsonFromText<unknown>(raw);
  if (!parsed || typeof parsed !== "object") return { ok: false, issues: ["The response was not a single JSON object."] };
  const result = creativeDirectionSchema.safeParse(normalizeDirectionJson(parsed));
  if (result.success) return { ok: true, direction: result.data, issues: [] };
  return {
    ok: false,
    issues: result.error.issues.slice(0, 8).map((i) => `${i.path.join(".") || "(root)"}: ${i.message}`),
  };
}

export interface GenerateDirectionParams {
  request: string;
  digest: SiteDigest;
  portfolioBlock: string;
  materialsText?: string;
  mode: "edit" | "create";
}

export type DirectionCompleteFn = typeof aiComplete;

// ---------------------------------------------------------------- normalization
// Models produce SCHEMATICALLY-valid directions that fail strict validation for
// REPRESENTATION reasons only: "Playfair Display" instead of the library id
// "playfair-display", "850" instead of 850, an 8-digit hex, a 320-char concept.
// normalizeDirectionJson repairs exactly those representations — ids still have
// to EXIST in the real libraries afterwards, so nothing security-relevant is
// weakened (the full schema validates everything that remains).

const slug = (v: string) => v.trim().toLowerCase().replace(/\s+/g, "-").replace(/[^a-z0-9-]/g, "");
/** Collapse-case key: "fadeUp" and "fade-up" both fold to "fadeup". */
const flat = (v: string) => v.trim().toLowerCase().replace(/[^a-z0-9]/g, "");
const FONT_BY_SLUG = new Map(SITE_FONTS.flatMap((f) => [f.id, slug(f.family)].map((k) => [k, f.id] as const)));
const FONT_IDS = new Set(SITE_FONTS.map((f) => f.id));

/** slug-of-id (dash-collapsed) → real id, built per motion scope. Keys include
 * BOTH the full flat id and the id without its conventional scope prefix
 * ("bg-spotlight-breathe" → "bgspotlightbreathe" AND "spotlightbreathe"),
 * because models habitually drop the prefix. */
function presetAliasMap(scope: "reveal" | "hover" | "background"): Map<string, string> {
  return new Map(
    motionPresetsByScope(scope).flatMap((p) => {
      const full = flat(p.id);
      const stripped = full.replace(/^(bg|hover|micro)/, "");
      const entries: [string, string][] = [[full, p.id]];
      if (stripped && stripped !== full) entries.push([stripped, p.id]);
      return entries;
    })
  );
}
const REVEAL_ALIASES = presetAliasMap("reveal");
const HOVER_ALIASES = presetAliasMap("hover");
const BG_ALIASES = presetAliasMap("background");
/** Common motion synonyms the model uses that are unambiguous in this registry. */
const PRESET_SYNONYMS: Record<string, string> = {
  letterbox: "media-cinema-open",
  letterboxreveal: "media-cinema-open",
  cinemaopen: "media-cinema-open",
  cinematicopen: "media-cinema-open",
  kenburns: "media-ken-burns",
  kenburn: "media-ken-burns",
  parallax: "parallax",
  fadein: "fade-only",
  fade: "fadeUp",
  reveal: "fadeUp",
  wipe: "media-wipe-soft",
  maskreveal: "maskReveal",
  zoomslow: "media-zoom-slow",
  grayscale: "media-grayscale-in",
  spotlight: "bg-spotlight-breathe",
  spotlightbreathe: "bg-spotlight-breathe",
  aurora: "bg-aurora-soft",
  aurasoft: "bg-aurora-soft",
  particles: "bg-particles-drift",
  particle: "bg-particles-drift",
  gradientpan: "bg-gradient-pan",
  glow: "hover-glow",
  glowhover: "hover-glow",
  shine: "hover-shine",
  lift: "hover-lift",
  magnetic: "hover-magnet",
  underline: "hover-underline",
  press: "hover-press",
  tilt: "hover-tilt",
  invert: "hover-invert",
  none: "fadeUp",
  noglow: "hover-lift",
};

function coerceScopedPreset(v: unknown, aliases: Map<string, string>): unknown {
  if (typeof v !== "string") return v;
  const key = flat(v);
  if (aliases.has(key)) return aliases.get(key);
  if (PRESET_SYNONYMS[key]) return PRESET_SYNONYMS[key];
  // containment fallback: model wrote "cinematic image reveal" → find the
  // registry id whose flat form appears inside the model's words.
  for (const [key2, id] of aliases) {
    if (key2.length >= 5 && key.includes(key2)) return id;
  }
  return slug(v);
}

function coerceFont(v: unknown): unknown {
  if (typeof v !== "string") return v;
  const raw = v.trim();
  if (FONT_IDS.has(raw)) return raw;
  const s = slug(raw);
  return FONT_BY_SLUG.get(s) ?? s;
}

function coercePresetId(v: unknown): unknown {
  return typeof v === "string" ? slug(v) : v;
}

function coerceHex(v: unknown): unknown {
  if (typeof v !== "string") return v;
  const t = v.trim();
  return /^#[0-9a-fA-F]{3,8}$/.test(t) ? t : v;
}

/** "16:9" → "16/9"; also fixes unicode-fraction or dash variants. */
function coerceImageRatio(v: unknown): unknown {
  if (typeof v !== "string") return v;
  const m = /^(4|3|1|16)\s*[:\-/]\s*(3|2|9|1)$/.exec(v.trim());
  return m ? `${m[1]}/${m[2]}` : v;
}

function coerceInt(v: unknown): unknown {
  if (typeof v === "string" && v.trim() !== "" && Number.isFinite(Number(v))) return Math.round(Number(v));
  return v;
}

const capStr = (v: unknown, max: number): unknown => (typeof v === "string" ? v.slice(0, max) : v);

function normalizeDirectionJson(raw: unknown): unknown {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return raw;
  const src = { ...(raw as Record<string, unknown>) };

  if (typeof src.designLanguage === "string") {
    const langKey = flat(src.designLanguage);
    const lang = DESIGN_LANGUAGE_IDS.find((id) => flat(id) === langKey);
    src.designLanguage = lang ?? slug(src.designLanguage);
  }
  for (const k of ["concept", "heroComposition", "mediaDirection", "responsiveStrategy"] as const) {
    const max = k === "concept" ? 600 : k === "heroComposition" ? 500 : k === "mediaDirection" ? 400 : 300;
    src[k] = capStr(src[k], max);
  }

  const u = src.understanding && typeof src.understanding === "object" && !Array.isArray(src.understanding)
    ? { ...(src.understanding as Record<string, unknown>) } : src.understanding;
  if (u && typeof u === "object") {
    for (const [k, v] of Object.entries(u as Record<string, unknown>)) {
      (u as Record<string, unknown>)[k] = capStr(v, k === "industry" ? 120 : 300);
    }
  }
  src.understanding = u;

  const pal = src.palette && typeof src.palette === "object" && !Array.isArray(src.palette)
    ? { ...(src.palette as Record<string, unknown>) } : src.palette;
  if (pal && typeof pal === "object") {
    const p = pal as Record<string, unknown>;
    for (const k of ["background", "surface", "foreground", "muted", "accent", "accent2"]) p[k] = coerceHex(p[k]);
    if (p.gradient && typeof p.gradient === "object" && !Array.isArray(p.gradient)) {
      const g = p.gradient as Record<string, unknown>;
      g.from = coerceHex(g.from);
      g.to = coerceHex(g.to);
      g.angle = coerceInt(g.angle);
    }
  }
  src.palette = pal;

  const typ = src.typography && typeof src.typography === "object" && !Array.isArray(src.typography)
    ? { ...(src.typography as Record<string, unknown>) } : src.typography;
  if (typ && typeof typ === "object") {
    const t = typ as Record<string, unknown>;
    for (const k of ["headingFont", "bodyFont", "accentFont", "codeFont"]) t[k] = coerceFont(t[k]);
    t.rationale = capStr(t.rationale, 300);
  }
  src.typography = typ;

  const mot = src.motion && typeof src.motion === "object" && !Array.isArray(src.motion)
    ? { ...(src.motion as Record<string, unknown>) } : src.motion;
  if (mot && typeof mot === "object") {
    const m = mot as Record<string, unknown>;
    m.preset = coerceScopedPreset(m.preset, REVEAL_ALIASES);
    m.hoverPreset = coerceScopedPreset(m.hoverPreset, HOVER_ALIASES);
    m.backgroundPreset = coerceScopedPreset(m.backgroundPreset, BG_ALIASES);
    if (typeof m.easing === "string") {
      const e = flat(m.easing);
      m.easing = (MOTION_EASING_IDS as readonly string[]).find((x) => flat(x) === e) ?? slug(m.easing);
    }
    for (const k of ["duration", "intensity", "stagger"]) m[k] = coerceInt(m[k]);
    if (typeof m.scrollProgress === "string") m.scrollProgress = m.scrollProgress.trim().toLowerCase() === "true";
    m.rationale = capStr(m.rationale, 300);
  }
  src.motion = mot;

  const lay = src.layout && typeof src.layout === "object" && !Array.isArray(src.layout)
    ? { ...(src.layout as Record<string, unknown>) } : src.layout;
  if (lay && typeof lay === "object") {
    const l = lay as Record<string, unknown>;
    for (const k of ["radius", "density", "contentWidth", "buttonStyle", "linkStyle", "divider", "navLayout"]) {
      if (typeof l[k] === "string") l[k] = slug(l[k] as string);
    }
    l.imageRatio = coerceImageRatio(l.imageRatio);
    l.surfaceOpacity = coerceInt(l.surfaceOpacity);
    if (typeof l.glassPreset === "string") l.glassPreset = slug(l.glassPreset);
    l.strategy = capStr(l.strategy, 400);
  }
  src.layout = lay;

  if (Array.isArray(src.sectionPlan)) {
    src.sectionPlan = src.sectionPlan.slice(0, 12).map((entry: unknown) => {
      if (!entry || typeof entry !== "object" || Array.isArray(entry)) return entry;
      const e = entry as Record<string, unknown>;
      return { section: capStr(e.section, 40), direction: capStr(e.direction, 300) };
    });
  }
  return src;
}

/**
 * Generate + validate the creative direction. ONE bounded repair round on
 * schema failure. Returns null on any failure — the pipeline proceeds without
 * a direction (honest degradation, never a fake).
 */
export async function generateCreativeDirection(
  params: GenerateDirectionParams,
  deps: { complete?: DirectionCompleteFn } = {}
): Promise<CreativeDirection | null> {
  const complete = deps.complete ?? aiComplete;
  const shortlist = matchDesignLanguages(params.request).map((l) => l.id);
  const userContent = directionUserPrompt({
    request: params.request,
    digest: params.digest,
    portfolioBlock: params.portfolioBlock,
    materialsText: params.materialsText,
    shortlist,
  });

  let raw: string;
  try {
    ({ text: raw } = await complete(DIRECTION_SYSTEM, [{ role: "user", content: userContent }], {
      temperature: 0.35,
      thinking: true,
      timeoutMs: AI_DEEP_TIMEOUT_MS,
      feature: "design-direction",
    }));
  } catch {
    return null;
  }

  let outcome = attemptDirection(raw);
  if (outcome.ok) return outcome.direction ?? null;
  console.warn(`[ai-design] creative direction rejected — ${outcome.issues.join(" | ").slice(0, 600)}`);

  // DETERMINISTIC SALVAGE — before spending the repair call: the model's
  // direction usually has a few invalid fields (invented preset names, a
  // font family instead of an id) and many perfectly valid ones. Fill ONLY
  // the failing fields from the matched design language / curated palette —
  // grounded in the real registries, never invented — and re-validate. If
  // the salvage passes the same schema, the direction is real; if not, the
  // one bounded model repair still runs.
  const salvaged = salvageDirection(raw, params.request);
  if (salvaged) return salvaged;

  // ONE bounded repair — the model sees its own output + the real issues.
  let repairText: string | null = null;
  try {
    const repair = await complete(
      [
        DIRECTION_SYSTEM,
        "",
        "REPAIR TASK: your previous answer was rejected by the direction schema validator. Fix EXACTLY these issues and return the corrected JSON object:",
        ...outcome.issues.map((i) => `- ${i}`),
        "",
        "Your previous (rejected) answer:",
        `"""${raw.slice(0, 12_000)}"""`,
        "",
        "Reminder of the schema:",
        DIRECTION_SCHEMA_DOC,
      ].join("\n"),
      [{ role: "user", content: userContent }],
      { temperature: 0.2, thinking: true, timeoutMs: AI_DEEP_TIMEOUT_MS, feature: "design-direction-repair" }
    );
    repairText = repair.text;
    outcome = attemptDirection(repair.text);
  } catch {
    return null;
  }
  if (!outcome.ok) {
    // Final deterministic salvage of the REPAIRED answer (same rule as above).
    const salvaged = repairText ? salvageDirection(repairText, params.request) : null;
    if (salvaged) return salvaged;
    console.warn(`[ai-design] creative direction repair also rejected — ${outcome.issues.join(" | ").slice(0, 600)}`);
    return null;
  }
  return outcome.direction ?? null;
}

/**
 * Fill ONLY schema-invalid fields from the matched design language and the
 * curated palette registry — everything else stays exactly as the model
 * wrote it. The salvaged object must pass the FULL schema; anything that
 * cannot be grounded returns null (no invention).
 */
function salvageDirection(rawText: string, request: string): CreativeDirection | null {
  const parsed = parseJsonFromText<Record<string, unknown>>(rawText);
  if (!parsed || typeof parsed !== "object") return null;
  const normalized = (normalizeDirectionJson(parsed) ?? {}) as Record<string, unknown>;

  const shortlist = matchDesignLanguages(request);
  const lang = shortlist[0] ?? DESIGN_LANGUAGES[0];
  const fallbackPalette = getPalette(lang.palettes[0]);

  const merged: Record<string, unknown> = { ...normalized };
  merged.designLanguage = lang.id;
  merged.concept = typeof merged.concept === "string" && merged.concept.trim().length >= 20 ? merged.concept : `${lang.tagline} Grounded in the user's own brief.`;

  // understanding — every field must be a real string; missing ones are
  // grounded in the request itself (the user's own words), never invented.
  const u = (merged.understanding && typeof merged.understanding === "object" && !Array.isArray(merged.understanding)
    ? { ...(merged.understanding as Record<string, unknown>) } : {}) as Record<string, unknown>;
  const reqSlice = (max: number) => request.replace(/\s+/g, " ").trim().slice(0, max);
  u.purpose = typeof u.purpose === "string" && u.purpose.trim().length >= 3 ? u.purpose.slice(0, 300) : reqSlice(300);
  u.brand = typeof u.brand === "string" && u.brand.trim().length >= 3 ? u.brand.slice(0, 300) : reqSlice(300);
  u.audience = typeof u.audience === "string" && u.audience.trim().length >= 3 ? u.audience.slice(0, 300) : "The user's own audience as described in their request.";
  u.industry = typeof u.industry === "string" && u.industry.trim().length >= 2 ? u.industry.slice(0, 120) : lang.label;
  u.personality = typeof u.personality === "string" && u.personality.trim().length >= 3 ? u.personality.slice(0, 300) : lang.tagline.slice(0, 300);
  u.colorPsychology = typeof u.colorPsychology === "string" && u.colorPsychology.trim().length >= 3 ? u.colorPsychology.slice(0, 300) : `Palette family: ${lang.palettes.join(", ")}.`;
  u.contentHierarchy = typeof u.contentHierarchy === "string" && u.contentHierarchy.trim().length >= 3 ? u.contentHierarchy.slice(0, 300) : lang.sectionDirection.slice(0, 300);
  merged.understanding = u;

  // palette — invalid/missing hexes come from the curated palette's REAL tokens.
  const pal = (merged.palette && typeof merged.palette === "object" && !Array.isArray(merged.palette)
    ? { ...(merged.palette as Record<string, unknown>) } : {}) as Record<string, unknown>;
  const hexOk = (v: unknown) => typeof v === "string" && /^#[0-9a-fA-F]{3,8}$/.test(v);
  const palTokens = fallbackPalette?.tokens;
  for (const [k, tokenKey] of [
    ["background", "background"], ["surface", "surface"], ["foreground", "foreground"],
    ["muted", "muted"], ["accent", "accent"], ["accent2", "accent2"],
  ] as const) {
    if (!hexOk(pal[k])) pal[k] = palTokens ? (palTokens as unknown as Record<string, string | undefined>)[tokenKey] ?? "#111111" : "#111111";
  }
  if (pal.gradient !== null && (typeof pal.gradient !== "object" || Array.isArray(pal.gradient))) pal.gradient = null;
  if (pal.gradient && typeof pal.gradient === "object") {
    const g = pal.gradient as Record<string, unknown>;
    if (!hexOk(g.from) || !hexOk(g.to) || typeof g.angle !== "number") pal.gradient = null;
  }
  merged.palette = pal;

  // typography — unknown fonts fold onto the language's real pairing.
  const typ = (merged.typography && typeof merged.typography === "object" && !Array.isArray(merged.typography)
    ? { ...(merged.typography as Record<string, unknown>) } : {}) as Record<string, unknown>;
  for (const [k, langKey] of [["headingFont", "heading"], ["bodyFont", "body"], ["accentFont", "accent"], ["codeFont", "code"]] as const) {
    const v = typ[k];
    if (typeof v !== "string" || !SITE_FONTS.some((f) => f.id === v)) typ[k] = lang.fonts[langKey];
  }
  const ENUMS: Record<string, readonly string[]> = {
    typeScale: ["intimate", "balanced", "grand"], headingWeight: ["light", "semibold", "bold"],
    letterSpacing: ["tight", "normal", "wide"], lineHeight: ["tight", "normal", "relaxed"],
  };
  for (const [k, allowed] of Object.entries(ENUMS)) {
    if (typeof typ[k] !== "string" || !(allowed as readonly string[]).includes(typ[k] as string)) {
      typ[k] = lang.tokens[k as keyof typeof lang.tokens] as string;
    }
  }
  typ.rationale = typeof typ.rationale === "string" && typ.rationale.trim().length >= 3 ? typ.rationale.slice(0, 300) : lang.fonts.note.slice(0, 300);
  merged.typography = typ;

  // motion — unknown presets fold onto the language's REAL motion language.
  const mot = (merged.motion && typeof merged.motion === "object" && !Array.isArray(merged.motion)
    ? { ...(merged.motion as Record<string, unknown>) } : {}) as Record<string, unknown>;
  const revealIds = motionPresetsByScope("reveal").map((p) => p.id);
  const hoverIds = motionPresetsByScope("hover").map((p) => p.id);
  const bgIds = motionPresetsByScope("background").map((p) => p.id);
  if (typeof mot.preset !== "string" || !revealIds.includes(mot.preset)) mot.preset = lang.motion.reveal;
  if (typeof mot.hoverPreset !== "string" || !hoverIds.includes(mot.hoverPreset)) mot.hoverPreset = lang.motion.hover;
  if (typeof mot.backgroundPreset !== "string" || !bgIds.includes(mot.backgroundPreset)) mot.backgroundPreset = lang.motion.background;
  if (typeof mot.easing !== "string" || !(MOTION_EASING_IDS as readonly string[]).includes(mot.easing)) mot.easing = lang.motion.easing;
  const intOk = (v: unknown, min: number, max: number) => typeof v === "number" && Number.isFinite(v) && v >= min && v <= max;
  if (!intOk(mot.duration, 150, 1200)) mot.duration = lang.motion.duration;
  if (!intOk(mot.intensity, 0, 100)) mot.intensity = lang.motion.intensity;
  if (!intOk(mot.stagger, 0, 240)) mot.stagger = 80;
  mot.scrollProgress = typeof mot.scrollProgress === "boolean" ? mot.scrollProgress : lang.motion.scrollProgress;
  mot.rationale = typeof mot.rationale === "string" && mot.rationale.trim().length >= 3 ? mot.rationale.slice(0, 300) : lang.motion.note.slice(0, 300);
  merged.motion = mot;

  // layout — invalid enums fold onto the language's token direction.
  const lay = (merged.layout && typeof merged.layout === "object" && !Array.isArray(merged.layout)
    ? { ...(merged.layout as Record<string, unknown>) } : {}) as Record<string, unknown>;
  const LAYOUT_ENUMS: Record<string, readonly string[]> = {
    radius: ["none", "md", "full"], density: ["compact", "regular", "relaxed"], contentWidth: ["narrow", "regular", "wide"],
    buttonStyle: ["sharp", "rounded", "pill", "outline"], linkStyle: ["underline", "accent", "plain"],
    imageRatio: ["4/3", "3/2", "1/1", "16/9"], divider: ["none", "line", "accent"], navLayout: ["inline", "stacked", "centered"],
  };
  for (const [k, allowed] of Object.entries(LAYOUT_ENUMS)) {
    if (typeof lay[k] !== "string" || !(allowed as readonly string[]).includes(lay[k] as string)) {
      lay[k] = lang.tokens[k as keyof typeof lang.tokens] as string;
    }
  }
  if (!intOk(lay.surfaceOpacity, 20, 100)) lay.surfaceOpacity = lang.tokens.surfaceOpacity;
  const GLASS_IDS = ["frosted", "smoked", "crystal", "aurora", "soft", "dark", "custom"];
  if (lay.glassPreset !== null && (typeof lay.glassPreset !== "string" || !GLASS_IDS.includes(lay.glassPreset))) {
    lay.glassPreset = lang.tokens.glass;
  }
  lay.strategy = typeof lay.strategy === "string" && lay.strategy.trim().length >= 3 ? lay.strategy.slice(0, 400) : lang.composition.join(" ").slice(0, 400);
  merged.layout = lay;

  merged.heroComposition = typeof merged.heroComposition === "string" && merged.heroComposition.trim().length >= 10 ? merged.heroComposition.slice(0, 500) : lang.composition[0].slice(0, 500);
  merged.sectionPlan = Array.isArray(merged.sectionPlan)
    ? (merged.sectionPlan as unknown[]).filter((e) => e && typeof e === "object" && !Array.isArray(e) && typeof (e as Record<string, unknown>).section === "string" && typeof (e as Record<string, unknown>).direction === "string").slice(0, 12)
    : [];
  merged.mediaDirection = typeof merged.mediaDirection === "string" && merged.mediaDirection.trim().length >= 3 ? merged.mediaDirection.slice(0, 400) : lang.media.slice(0, 400);
  merged.responsiveStrategy = typeof merged.responsiveStrategy === "string" && merged.responsiveStrategy.trim().length >= 3 ? merged.responsiveStrategy.slice(0, 300) : lang.responsive.slice(0, 300);

  const result = creativeDirectionSchema.safeParse(merged);
  return result.success ? result.data : null;
}

// ---------------------------------------------------------------------------
// Deterministic token patch derived from the direction — validated by the
// SAME designPatchSchema the executor applies, so a direction can never carry
// a token the safe pipeline would reject.
// ---------------------------------------------------------------------------

export function directionTokenPatch(direction: CreativeDirection): DesignPatch | null {
  const candidate = {
    theme: {
      background: direction.palette.background,
      foreground: direction.palette.foreground,
      accent: direction.palette.accent,
      accent2: direction.palette.accent2,
      surface: direction.palette.surface,
      muted: direction.palette.muted,
      gradient: direction.palette.gradient,
      surfaceOpacity: direction.layout.surfaceOpacity,
      radius: direction.layout.radius,
      density: direction.layout.density,
      typeScale: direction.typography.typeScale,
      lineHeight: direction.typography.lineHeight,
      letterSpacing: direction.typography.letterSpacing,
      headingWeight: direction.typography.headingWeight,
      contentWidth: direction.layout.contentWidth,
      buttonStyle: direction.layout.buttonStyle,
      linkStyle: direction.layout.linkStyle,
      imageRatio: direction.layout.imageRatio,
      divider: direction.layout.divider,
      pageTransition: direction.motion.pageTransition,
      navLayout: direction.layout.navLayout,
      headingFont: direction.typography.headingFont,
      bodyFont: direction.typography.bodyFont,
      accentFont: direction.typography.accentFont,
      codeFont: direction.typography.codeFont,
      ...(direction.layout.glassPreset
        ? { glass: { enabled: true, preset: direction.layout.glassPreset } }
        : {}),
    },
    motion: {
      enabled: true,
      preset: direction.motion.preset,
      duration: direction.motion.duration,
      intensity: direction.motion.intensity,
      easing: direction.motion.easing,
      stagger: direction.motion.stagger,
      hoverEffects: true,
      scrollReveal: true,
      once: true,
      background: direction.motion.backgroundPreset,
      microInteractions: direction.motion.hoverPreset,
      scrollProgress: direction.motion.scrollProgress,
    },
  };
  const parsed = designPatchSchema.safeParse(candidate);
  return parsed.success ? parsed.data : null;
}

/** Compact prompt block — injected into the planner, the compose step and every model step. */
export function directionPromptBlock(direction: CreativeDirection): string {
  const lang = getDesignLanguage(direction.designLanguage);
  const swatches = [
    `bg ${direction.palette.background}`,
    `surface ${direction.palette.surface}`,
    `fg ${direction.palette.foreground}`,
    `muted ${direction.palette.muted}`,
    `accent ${direction.palette.accent}`,
    `accent2 ${direction.palette.accent2}`,
  ].join(" · ");
  const gradient = direction.palette.gradient
    ? `\nGradient: ${direction.palette.gradient.from} → ${direction.palette.gradient.to} @ ${direction.palette.gradient.angle}deg`
    : "";
  const sections = direction.sectionPlan.length
    ? direction.sectionPlan.map((s) => `${s.section}: ${s.direction}`).join(" | ")
    : "(no per-section plan)";
  return [
    "BINDING CREATIVE DIRECTION (generated for THIS request — every step must realize it; do not contradict it, do not restyle outside it):",
    `Design language: ${lang?.label ?? direction.designLanguage} (${direction.designLanguage})`,
    `Concept: ${direction.concept}`,
    `Brief — purpose: ${direction.understanding.purpose} · brand: ${direction.understanding.brand} · audience: ${direction.understanding.audience} · industry: ${direction.understanding.industry} · personality: ${direction.understanding.personality}`,
    `Color psychology: ${direction.understanding.colorPsychology}`,
    `Palette: ${swatches}${gradient}`,
    `Typography: heading ${direction.typography.headingFont} / body ${direction.typography.bodyFont} / accent ${direction.typography.accentFont} / code ${direction.typography.codeFont} (${direction.typography.typeScale} scale, ${direction.typography.headingWeight} headings) — ${direction.typography.rationale}`,
    `Motion: ${direction.motion.preset} @ ${direction.motion.duration}ms / ${direction.motion.intensity}% (${direction.motion.easing}) · hover ${direction.motion.hoverPreset} · background ${direction.motion.backgroundPreset} · page transition ${direction.motion.pageTransition}${direction.motion.scrollProgress ? " · scroll progress bar" : ""} — ${direction.motion.rationale}`,
    `Layout: radius ${direction.layout.radius} · density ${direction.layout.density} · width ${direction.layout.contentWidth} · buttons ${direction.layout.buttonStyle} · links ${direction.layout.linkStyle} · images ${direction.layout.imageRatio} · divider ${direction.layout.divider} · surface opacity ${direction.layout.surfaceOpacity}${direction.layout.glassPreset ? ` · glass preset ${direction.layout.glassPreset}` : ""} — ${direction.layout.strategy}`,
    `Hero: ${direction.heroComposition}`,
    `Per-section direction: ${sections}`,
    `Media: ${direction.mediaDirection}`,
    `Responsive: ${direction.responsiveStrategy}`,
    `Content hierarchy: ${direction.understanding.contentHierarchy}`,
  ].join("\n");
}

/**
 * Prepend ONE deterministic "apply the creative direction" step when the
 * model's plan did not already apply the direction's tokens itself. The
 * injected step carries the direction patch (already designPatchSchema-valid)
 * and is re-validated through the SAME plan schema + digest validator — if
 * anything fails validation the injection is dropped (never a bypass).
 */
export function withDirectionStep(
  plan: import("@/lib/ai-design/plan").DesignPlan,
  direction: CreativeDirection,
  revalidate: (plan: import("@/lib/ai-design/plan").DesignPlan) => boolean
): { plan: typeof plan; injected: boolean } {
  const patch = directionTokenPatch(direction);
  if (!patch) return { plan, injected: false };
  const hasCompose = plan.steps.some((s) => s.tool === "site.compose");
  const hasTokenStep = plan.steps.some((s) => s.tool === "theme.tokens");
  if (hasCompose || hasTokenStep || plan.steps.length >= 8) return { plan, injected: false };
  const step: PlanStep = {
    id: "direction-tokens",
    title: "Apply the creative direction's design tokens",
    tool: "theme.tokens",
    kind: "design",
    targets: [],
    summary: "Establish the creative direction's palette, typography, layout and motion tokens first, so every later step builds on one coherent visual system.",
    instruction: "",
    patch,
    dependsOn: [],
    risk: "low",
  };
  const candidate = { ...plan, steps: [step, ...plan.steps] };
  return revalidate(candidate) ? { plan: candidate, injected: true } : { plan, injected: false };
}

/**
 * Quota-conscious heuristic: only large, clearly design-oriented requests get
 * a direction pass (the direction costs one model call). Short edit requests
 * ("fix the spacing") and general questions skip it — the planner behaves
 * exactly as before for them.
 */
export function shouldBuildDirection(request: string): boolean {
  const text = request.trim();
  if (text.length < 220) return false;
  const signals = [
    "website", "portfolio", "site", "homepage", "landing", "redesign", "rebuild",
    "design", "create ", "build ", "make me", "brand", "identity", "visual",
    "cinematic", "luxury", "minimal", "editorial", "premium", "professional",
    "sections", "pages", "hero", "showreel", "gallery",
  ];
  const lower = text.toLowerCase();
  return signals.some((s) => lower.includes(s));
}
